import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { vec2, uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Vector3, Color } = ctx.THREE;
  const group = new Group();

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const anims = [];

  // 1. STAGE BACKDROP (Engineered Gradient Surface)
  // Dimensions to fill the frame nicely (approx 7x6 units at z=-2.5)
  const bgGeo = new PlaneGeometry(7.2, 5.8);
  const bgMat = new MeshBasicNodeMaterial({
    depthWrite: false,
    depthTest: true
  });

  // Vertical gradient matching our visual palette, transitioning from deep dark base up to accent/paper hint
  const uvNode = uv();
  const baseColor = color(new Color(colors.surface));
  const topColor = color(new Color(colors.ink));
  const gradient = mix(baseColor, topColor, uvNode.y);
  bgMat.colorNode = gradient;

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // 2. HERO SHOWPIECE SPRITE
  // Atlas size: 512, 320 -> Aspect ratio: 1.6
  const width = 4.2;
  const height = width / 1.6;
  const spriteGeo = new PlaneGeometry(width, height);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaTest: 0.05,
    depthWrite: false
  });

  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.set(0, 0, 0);
  group.add(spriteMesh);

  // Load the texture and apply atlas coordinates
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = 'srgb';
      // Atlas Region 0, 0, 512, 320. If it's a full atlas map, specify offsets. 
      // Assuming it's already bounded/standalone or offset UV in shader:
      const uvs = spriteGeo.attributes.uv;
      // Map UVs to the specific atlas sub-region: [0, 0, 512, 320] inside full texture (assuming 512x512 for standard atlas block)
      const atlasW = 512;
      const atlasH = 320;
      const texW = 512;
      const texH = 512;

      const uMin = 0 / texW;
      const uMax = atlasW / texW;
      const vMin = (texH - atlasH) / texH; // Flip standard V axis for upper-left mapping
      const vMax = 1.0;

      for (let i = 0; i < uvs.count; i++) {
        let u = uvs.getX(i);
        let v = uvs.getY(i);
        u = uMin + u * (uMax - uMin);
        v = vMin + v * (vMax - vMin);
        uvs.setXY(i, u, v);
      }
      uvs.needsUpdate = true;

      spriteMat.map = texture;
      spriteMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading hero showpiece texture:", err);
    });
  }

  // 3. MOTION (Static composition: weighted subtle floating entrance, no interactivity)
  // Gentle entrance for the overall hub component
  spriteMesh.position.y = -0.3;
  spriteMesh.scale.set(0.95, 0.95, 1.0);

  const enterTl = gsap.timeline();
  enterTl.to(spriteMesh.position, {
    y: 0,
    duration: 1.2,
    ease: "power4.out"
  });
  enterTl.to(spriteMesh.scale, {
    x: 1.0,
    y: 1.0,
    duration: 1.4,
    ease: "power3.out"
  }, "<");

  // Subtle breathing animation for a living showcase feel
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(spriteMesh.position, {
    y: 0.05,
    duration: 5.0,
    ease: "sine.inOut"
  });

  anims.push(enterTl, breatheTl);

  // 4. CLEANUP
  group.userData.cleanup = () => {
    anims.forEach((t) => t.kill());
    bgGeo.dispose();
    bgMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();
  };

  return group;
}
